-- @seq 386
CREATE FUNCTION public.crm_has_tenant_access(p_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$ SELECT platform_is_tenant_member(p_tenant_id); $$;

-- @seq 515
CREATE FUNCTION public.platform_party_add_role(p_party_id uuid, p_role text, p_details jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE p platform_parties%ROWTYPE; v uuid; v_first text; v_last text; v_name text;
BEGIN
  SELECT * INTO p FROM platform_parties WHERE id = p_party_id;
  IF NOT FOUND OR p.merged_into_id IS NOT NULL THEN RAISE EXCEPTION 'Party not found'; END IF;
  PERFORM acct_assert_access(p.tenant_id);
  v_name := coalesce(p_details->>'name', p.display_name, p.email_normalized);
  IF v_name IS NULL THEN RAISE EXCEPTION 'Party needs a name or email'; END IF;
  v_first := coalesce(p_details->>'first_name', CASE WHEN p.party_kind = 'person' THEN split_part(v_name, ' ', 1) END);
  v_last  := coalesce(p_details->>'last_name',  CASE WHEN p.party_kind = 'person' AND position(' ' in v_name) > 0 THEN substr(v_name, position(' ' in v_name) + 1) END);
  CASE p_role
    WHEN 'customer' THEN
      SELECT id INTO v FROM crm_customers WHERE party_id = p.id LIMIT 1;
      IF v IS NULL THEN
        INSERT INTO crm_customers(tenant_id, party_id, customer_type, lifecycle_stage, lifecycle_status, first_name, last_name, company_name, email, phone, country)
        VALUES (p.tenant_id, p.id, CASE WHEN p.party_kind = 'organization' THEN 'business' ELSE 'individual' END, 'customer', 'active',
                v_first, v_last, CASE WHEN p.party_kind = 'organization' THEN v_name END, p.email_normalized, p.phone, coalesce(p_details->>'country', 'US'))
        RETURNING id INTO v;
      END IF;
    WHEN 'vendor', 'supplier', 'contractor' THEN
      -- one payables record per party per entity: supplier/contractor are kinds of vendor, so an
      -- existing vendor is upgraded instead of duplicated (1099 totals and AP aging stay on one record)
      SELECT id INTO v FROM acct_vendors WHERE party_id = p.id AND entity_id = acct_default_entity(p.tenant_id)
       ORDER BY (vendor_kind = p_role) DESC, created_at LIMIT 1;
      IF v IS NULL THEN
        INSERT INTO acct_vendors(tenant_id, entity_id, party_id, vendor_number, legal_name, display_name, company_name, first_name, last_name, email, phone,
                                 vendor_kind, is_1099_vendor, tax_form_type)
        VALUES (p.tenant_id, acct_default_entity(p.tenant_id), p.id, NULL, coalesce(p_details->>'legal_name', v_name), v_name,
                CASE WHEN p.party_kind = 'organization' THEN v_name END, v_first, v_last, p.email_normalized, p.phone, p_role,
                p_role = 'contractor', CASE WHEN p_role = 'contractor' THEN '1099-NEC' END)
        RETURNING id INTO v;
      ELSIF p_role <> 'vendor' THEN
        UPDATE acct_vendors SET vendor_kind = CASE WHEN vendor_kind = 'vendor' THEN p_role ELSE vendor_kind END,
               is_1099_vendor = is_1099_vendor OR p_role = 'contractor',
               tax_form_type = CASE WHEN p_role = 'contractor' THEN coalesce(tax_form_type, '1099-NEC') ELSE tax_form_type END,
               updated_at = now()
         WHERE id = v;
      END IF;
    WHEN 'stakeholder' THEN
      PERFORM platform__assert_tenant_admin(p.tenant_id);
      SELECT id INTO v FROM cap_stakeholders WHERE party_id = p.id LIMIT 1;
      IF v IS NULL THEN
        INSERT INTO cap_stakeholders(tenant_id, party_id, name, email, stakeholder_type)
        VALUES (p.tenant_id, p.id, v_name, p.email_normalized, coalesce(p_details->>'stakeholder_type', CASE WHEN p.party_kind = 'organization' THEN 'entity' ELSE 'other' END))
        RETURNING id INTO v;
      END IF;
    ELSE RAISE EXCEPTION 'Unknown role % (customer, vendor, supplier, contractor, stakeholder)', p_role;
  END CASE;
  RETURN v;
END $$;

-- @seq 516
CREATE FUNCTION public.platform_party_backfill(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS TABLE(table_name text, rows_linked bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE r record; n bigint;
BEGIN
  IF p_tenant_id IS NULL THEN
    IF NOT (platform_is_admin() OR coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role'
            OR current_user IN ('postgres','supabase_admin')) THEN
      RAISE EXCEPTION 'All-tenant backfill is for platform admins; pass a tenant id';
    END IF;
  ELSE
    PERFORM platform__assert_tenant_admin(p_tenant_id);
  END IF;
  FOR r IN SELECT s.table_name t FROM platform_party_sources s WHERE to_regclass('public.' || quote_ident(s.table_name)) IS NOT NULL ORDER BY 1 LOOP
    EXECUTE format('UPDATE public.%I SET party_id = NULL WHERE party_id IS NULL AND tenant_id IS NOT NULL AND ($1 IS NULL OR tenant_id = $1)', r.t)
      USING p_tenant_id;
    GET DIAGNOSTICS n = ROW_COUNT;
    table_name := r.t; rows_linked := n; RETURN NEXT;
  END LOOP;
END $_$;

-- @seq 517
CREATE FUNCTION public.platform_party_merge(p_from uuid, p_into uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE f platform_parties; t platform_parties; r record; n int := 0; m int;
BEGIN
  SELECT * INTO f FROM platform_parties WHERE id = p_from FOR UPDATE;
  SELECT * INTO t FROM platform_parties WHERE id = p_into FOR UPDATE;
  IF f.id IS NULL OR t.id IS NULL THEN RAISE EXCEPTION 'Party not found'; END IF;
  IF f.tenant_id <> t.tenant_id THEN RAISE EXCEPTION 'Parties belong to different tenants'; END IF;
  IF f.id = t.id OR t.merged_into_id IS NOT NULL THEN RAISE EXCEPTION 'Cannot merge into this party'; END IF;
  PERFORM platform__assert_tenant_admin(f.tenant_id);
  FOR r IN SELECT s.table_name x FROM platform_party_sources s WHERE to_regclass('public.' || quote_ident(s.table_name)) IS NOT NULL LOOP
    EXECUTE format('UPDATE public.%I SET party_id = $1 WHERE party_id = $2', r.x) USING p_into, p_from;
    GET DIAGNOSTICS m = ROW_COUNT; n := n + m;
  END LOOP;
  UPDATE platform_parties SET merged_into_id = p_into, updated_at = now() WHERE id = p_from;
  UPDATE platform_parties SET email_normalized = coalesce(email_normalized, f.email_normalized),
         phone = coalesce(phone, f.phone), display_name = coalesce(display_name, f.display_name), updated_at = now()
   WHERE id = p_into
     AND NOT EXISTS (SELECT 1 FROM platform_parties x WHERE x.tenant_id = t.tenant_id AND x.email_normalized = f.email_normalized
                      AND x.merged_into_id IS NULL AND x.id <> p_into);
  RETURN n;
END $_$;

